# 1. Mount Drive (for saving the trained .pth back out of the ephemeral VM).
#    force_remount=False is fine — it no-ops if already mounted.
from google.colab import drive
drive.mount('/content/drive')

# 1b. Download + extract dataset ZIP into /content/ (fast local SSD — avoids
#     Drive's rate limits for many small files). ZIP is committed in repo
#     alongside this script.
import urllib.request, zipfile, io, pathlib
DATASET_ZIP_URL = "https://raw.githubusercontent.com/flowa7021-source/OCR-tool/claude/easyocr-integration-review-3e9pP/colab_release/finetune_ru_colab.zip"
LOCAL_DATASET_DIR = pathlib.Path("/content/finetune_ru")
if not (LOCAL_DATASET_DIR / 'training' / 'labels.csv').exists():
    print(f'Downloading dataset ZIP from {DATASET_ZIP_URL} …')
    req = urllib.request.Request(DATASET_ZIP_URL, headers={'User-Agent': 'colab'})
    with urllib.request.urlopen(req) as r:
        blob = r.read()
    print(f'Downloaded {len(blob) / 1e6:.1f} MB. Extracting …')
    with zipfile.ZipFile(io.BytesIO(blob)) as zf:
        zf.extractall('/content')
    print(f'Dataset extracted to {LOCAL_DATASET_DIR}')
else:
    print(f'Dataset already present at {LOCAL_DATASET_DIR}')
# Sanity check — trainer needs labels.csv + .jpgs in each split.
for split in ('training', 'validation'):
    p = LOCAL_DATASET_DIR / split
    csv = p / 'labels.csv'
    jpgs = list(p.glob('*.jpg'))
    assert csv.exists(), f'Missing {csv}'
    print(f'  {split}: {csv} ({csv.stat().st_size / 1e3:.0f} KB), {len(jpgs)} jpgs')

# 2. Install deps (use Colab's pre-installed torch/torchvision/numpy — only add
#    the trainer's extras. Pinning torch==2.0.1 fails on modern Colab Python.)
